"""Count the tests generated by pankti-generate per target method (#PANKTI_TESTS) and compare with #UNIQUE.

usage: count_generated_tests.py <generated_tests_dir> <invoked-methods.csv> <out_prefix> [--unique <profile_stats.csv>]

pankti-generate (commit 0fddf27) writes one class Test<Class>PanktiGen per target class, in the target's package,
with one @Test method per unique object profile, named "test" + method name (first letter in upper case)
+ a suffix with the parameter types when the method is overloaded + a counter. A test is attributed to the target
of its class whose name gives the longest match, so that e.g. getFontFile tests are not counted for getFont.

With --unique, the counts are compared with #UNIQUE from analysis/profile_stats.py --fragments.
Writes <out_prefix>.csv (one row per target method) and <out_prefix>.txt (summary).
"""
import csv
import re
import sys
from collections import Counter
from pathlib import Path

TEST = re.compile(r"public void (test\w+)\(\)")


def targets_by_class(invoked_csv):
    by_class = {}
    with open(invoked_csv, newline="", encoding="utf-8") as f:
        for r in csv.DictReader(f):
            by_class.setdefault(r["parent-FQN"], []).append((r["method-name"], r["param-list"].replace(" ", "")))
    return by_class


def attribute(test_name, methods):
    """The target method (name, params) a test belongs to, or None."""
    best = None
    for name, params in methods:
        stem = "test" + name[0].upper() + name[1:]
        rest = test_name[len(stem):]
        if test_name.startswith(stem) and re.fullmatch(r"(_\w*?)?\d+", rest):
            if best is None or len(name) > len(best[0]):
                best = (name, params)
    return best


def main(argv):
    if len(argv) < 4:
        print(__doc__)
        return 2
    root, invoked, out = Path(argv[1]), argv[2], Path(argv[3])
    unique = {}
    if "--unique" in argv:
        with open(argv[argv.index("--unique") + 1], newline="", encoding="utf-8") as f:
            unique = {(r["class"], r["method"], r["params"].replace(" ", "")): int(r["unique"]) for r in csv.DictReader(f)}
    by_class = targets_by_class(invoked)
    counts, unattributed, classes = Counter(), [], 0
    for java in sorted(root.rglob("Test*PanktiGen.java")):
        classes += 1
        text = java.read_text(encoding="utf-8", errors="replace")
        package = re.search(r"^package ([\w.]+);", text, re.M).group(1)
        cls = package + "." + java.stem[len("Test"):-len("PanktiGen")]
        for test in TEST.findall(text):
            m = attribute(test, by_class.get(cls, []))
            if m:
                counts[(cls, m[0], m[1])] += 1
            else:
                unattributed.append(f"{cls}.{test}")

    keys = sorted(set(counts) | set(unique) | {(c, n, p) for c, ms in by_class.items() for n, p in ms})
    rows = [{"class": k[0], "method": k[1], "params": k[2], "pankti_tests": counts.get(k, 0),
             "unique": unique.get(k, ""), "equal": (counts.get(k, 0) == unique[k]) if k in unique else ""}
            for k in keys]
    out.parent.mkdir(parents=True, exist_ok=True)
    with open(f"{out}.csv", "w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=list(rows[0]), lineterminator="\n")
        w.writeheader()
        w.writerows(rows)
    lines = [f"test classes: {classes}; tests: {sum(counts.values()):,}; target methods with tests: {len(counts)}",
             f"tests not attributed to a target: {len(unattributed)}"] + [f"  {t}" for t in unattributed[:20]]
    if unique:
        diff = [r for r in rows if r["equal"] is False]
        lines.append(f"#PANKTI_TESTS = #UNIQUE for {sum(1 for r in rows if r['equal'] is True)} of "
                     f"{sum(1 for r in rows if r['unique'] != '')} methods (total {sum(counts.values()):,} vs "
                     f"{sum(unique.values()):,})")
        lines += [f"  {r['class']}.{r['method']}({r['params']}): {r['pankti_tests']} tests, {r['unique']} unique"
                  for r in diff]
    text = "\n".join(lines) + "\n"
    Path(f"{out}.txt").write_text(text, encoding="utf-8", newline="\n")
    print(text, end="")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
